<?php partial('account_nav',['route'=>$route]); ?>
<section class="page-hero"><div><span class="eyebrow">SMALL STEPS / REAL PROGRESS</span><h1><?= e($title) ?></h1><p><?= t('Earn rewards for verified participation, not button clicks. Daily tasks reset at midnight in the site timezone.') ?></p></div><span class="page-hero-art"><?= icon('gift') ?></span></section><div class="task-grid">
<?php $tasks=$a->db->all('SELECT * FROM cy_tasks WHERE active=1 ORDER BY sort_order,id LIMIT 100');foreach($tasks as $task):$progress=$a->tasks->progress($task,$me);$ready=$progress['count']>=(int)$task['target_count']; ?>
<article class="task-card panel glass reveal <?= $progress['claimed']?'is-complete':'' ?>"><div class="row between"><span class="task-icon"><?= icon($task['metric']==='checkin'?'sun':'sparkles') ?></span><span class="pill"><?= t($task['period']) ?></span></div><h2><?= e($task['name']) ?></h2><p><?= e($task['description']) ?></p><div class="task-rewards"><strong>+<?= (int)$task['reward_points'] ?> <?= t('Points') ?></strong><span>+<?= (int)$task['reward_xp'] ?> XP</span></div><label class="task-progress-label" for="task-progress-<?= (int)$task['id'] ?>"><?= t('Progress') ?> <span><?= (int)$progress['count'] ?>/<?= (int)$task['target_count'] ?></span></label><progress id="task-progress-<?= (int)$task['id'] ?>" value="<?= (int)$progress['count'] ?>" max="<?= (int)$task['target_count'] ?>"></progress>
<?php if($progress['claimed']): ?><span class="btn secondary full" aria-disabled="true"><?= icon('check') ?><?= t('Claimed') ?></span><?php elseif($ready): ?><?= form_start('task_claim') . hidden('task_id',$task['id']) ?><?php button('Claim reward','full','gift'); ?></form><?php else: $destination=['checkin'=>'wallet','comments'=>'articles','posts'=>'write','profile'=>'profile'][$task['metric']]; ?><a class="btn secondary full" href="<?= e(url($destination)) ?>"><?= t('Continue task') ?><?= icon('arrow') ?></a><?php endif ?></article><?php endforeach ?></div><?php if(!$tasks){empty_state('No tasks are published yet.','gift');} ?>
